using namespace hyperion;namespace hf=hyperion::flight;
namespace {
int checks=0;void check(bool b,const char* why){checks++;if(!b)throw std::runtime_error(why);}
bool close(double a,double b){return std::abs(a-b)<1e-7;}
int target(Game& g,const std::string& id){g.prepareWorldObjects();for(int i=0;i<int(g.s.flight.worldObjects.size());i++)if(g.s.flight.worldObjects[i].id==id)return i;throw std::runtime_error("Missing target "+id);}
void freeShip(Game& g){auto& f=g.s.flight;f.docked=false;f.dockedPort=-1;f.savedDock.clear();f.deployed=false;f.cancelNavigation();f.launchAssist=0;f.ship.velocity={};f.ship.throttle=0;g.s.economy.docked.clear();}
void calm(Game& g){g.s.economy.missions.clear();g.s.economy.missionClock.clear();g.s.economy.captains.clear();g.s.economy.pirates.clear();g.s.flight.traffic.clear();}
std::string fixture(Game& g,int kind,bool orbit=false,int faction=0){g.enterFlight();auto& site=g.s.economy.settlements.front();site.owner=faction;site.stock.fill(1000);site.built[kind]=std::max(1,site.built[kind]);g.ensureFlight();calm(g);int port=g.flightPort(site.id,orbit);g.s.flight.ship.position=g.s.flight.ports[port].position+g.s.flight.ports[port].normal*60;freeShip(g);return orbit?portObjectId("orbit:"+site.id):facilityObjectId(site.id,kind,0);}
void approach(Game& g,const std::string& id){auto& d=g.s.economy.worldDamage.at(id);freeShip(g);g.s.flight.ship.position=d.position+d.normal*45;g.s.flight.ship.previous=g.s.flight.ship.position;}
void damage(Game& g,const std::string& id,double amount=1e8,bool player=true){int i=target(g,id);auto o=g.s.flight.worldObjects[i];g.s.flight.damageWorld(i,amount,-1,o.position,player,player?"NOMA":"environment");g.processFlightEvents();}
int jobIndex(Game& g,const std::string& id,int kind){for(int i=0;i<int(g.s.economy.missions.size());i++)if(g.s.economy.missions[i].target==id&&g.s.economy.missions[i].kind==kind)return i;throw std::runtime_error("Missing disaster commission");}
void accept(Game& g,const std::string& root,int kind){auto id=g.s.economy.missions[jobIndex(g,root,kind)].id;g.action("acceptMission",id);check(g.s.economy.missions[jobIndex(g,root,kind)].state==MissionActive,"Disaster commission failed acceptance");}
void kit(Game& g){Stock s{};s[Components]=20;s[Crystal]=5;s[Alloy]=10;s[Rations]=5;g.storeShipStock(s);}
void conservation(const RecoveryState& r){check(r.initialCrew==r.crew+r.aboard+r.delivered+r.lost,"People disappeared or duplicated");for(int i=0;i<goodCount;i++)check(close(r.initial[i],r.sealed[i]+r.recovered[i]+r.destroyed[i]),"Recovery inventory not conserved");}
void roundtrip(Game& g){auto j=encodeEconomy(g.s.economy);check(encodeEconomy(decodeEconomy(j,g.universe,g.s.hours))==j,"Recovery state failed exact economy roundtrip");}
}
