 {Game g;auto id=fixture(g,Reactor);int i=target(g,id);auto o=g.s.flight.worldObjects[i];auto at=o.position+o.right*(o.half.x*.9);g.s.flight.damageWorld(i,o.capacity*.31,-1,at,true);g.processFlightEvents();auto& d=g.s.economy.worldDamage.at(id);check(close(d.integrity,.69)&&d.structure.sections[1]==0&&d.structure.sections[0]==1,"Aimed side hit did not detach only its section");check(workingBuildings(g.s.economy.settlements.front(),Reactor)>0,"Side breach disabled the entire facility");g.prepareWorldObjects();auto p=std::find_if(g.s.flight.worldObjects.begin(),g.s.flight.worldObjects.end(),[&](const auto& a){return a.kind==DebrisObject&&a.owner==id;});check(p!=g.s.flight.worldObjects.end(),"Detached side has no physical debris");auto piece=*p;check(std::isfinite(hf::worldObjectHit(piece.position-piece.up*100,piece.position+piece.up*100,piece)),"Debris has no swept collision");int cell=piece.fragment;int index=int(p-g.s.flight.worldObjects.begin());g.s.flight.damageWorld(index,piece.capacity*.6,-1,piece.position,true);g.processFlightEvents();check(d.structure.debrisHP[cell]>.39&&d.structure.debrisHP[cell]<.41,"Partial fragment damage not persistent");g.prepareWorldObjects();p=std::find_if(g.s.flight.worldObjects.begin(),g.s.flight.worldObjects.end(),[&](const auto& a){return a.owner==id&&a.fragment==cell&&a.kind==DebrisObject;});g.s.flight.damageWorld(int(p-g.s.flight.worldObjects.begin()),piece.capacity,-1,piece.position,true);g.processFlightEvents();check(d.structure.cleared&(1u<<cell),"Destroyed fragment not removed");roundtrip(g);}
