 {Game g;auto root=fixture(g,Habitat,true,1);kit(g);damage(g,root,1e8,false);auto& e=g.s.economy;auto& r=e.worldDamage.at(root).recovery;check(r.valid&&r.crew>0&&r.charge>0,"Station loss lacks rescue and hazards");auto frozen=encodeEconomy(e);g.action("recoveryCut",root);check(encodeEconomy(e)==frozen&&g.s.hours==0,"Cockpit recovery work must require turn-based planning");g.openStrategy();accept(g,root,EvacuationMission);approach(g,root);g.action("recoveryStabilize",root);check(r.stabilized&&close(g.shipStock()[Components],18),"Stabilization did not spend finite materials");approach(g,root);int turn=g.s.turns;g.action("recoveryRescue",root);check(g.s.turns==turn+1&&r.crew==0&&r.aboard==r.initialCrew,"Evacuation did not move actual people in one turn");auto site=e.settlements.front().id;int port=g.flightPort(site,false);g.s.flight.dockAt(port);g.processFlightEvents();g.action("recoveryDeliver",root);check(r.aboard==0&&r.delivered==r.initialCrew,"Evacuees not delivered into real settlement");conservation(r);roundtrip(g);auto missionId=e.missions[jobIndex(g,root,EvacuationMission)].id;check(e.missions[jobIndex(g,root,EvacuationMission)].state==MissionReady,"Evacuation contract not ready after delivery");auto credits=e.credits;auto escrow=e.missions[jobIndex(g,root,EvacuationMission)].escrow;g.action("debriefMission",missionId);check(e.credits==credits+escrow,"Evacuation reward not paid from reserved escrow");}
